import{_ as a,o as s,c as r,a3 as t}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"HADash v0.9.4 – Version préliminaire","description":"HADash propose désormais une interface Windows simplifiée ; le système de thèmes personnalisés a été supprimé.","frontmatter":{"title":"HADash v0.9.4 – Version préliminaire","description":"HADash propose désormais une interface Windows simplifiée ; le système de thèmes personnalisés a été supprimé.","date":"2026-08-02","author":"UGSo Software","tags":["HADash","Home Assistant","Windows"]},"headers":[],"relativePath":"fr/blog/posts/hadash-preview.md","filePath":"fr/blog/posts/hadash-preview.md","lastUpdated":1793123188000}'),i={name:"fr/blog/posts/hadash-preview.md"};function o(n,e,l,d,p,h){return s(),r("div",null,[...e[0]||(e[0]=[t('<p><a id="statut"></a></p><h1 id="hadash-v0-9-4-preview" tabindex="-1">HADash v0.9.4 – Version préliminaire <a class="header-anchor" href="#hadash-v0-9-4-preview" aria-label="Permalink to &quot;HADash v0.9.4 – Version préliminaire {#hadash-v0-9-4-preview}&quot;">​</a></h1><p><strong>2 août 2026 · HADash</strong></p><p>Avec la version <strong>v0.9.4-preview</strong>, l&#39;interface utilisateur de HADash a été simplifiée.</p><h2 id="was-wurde-geandert" tabindex="-1">Qu&#39;est-ce qui a changé ? <a class="header-anchor" href="#was-wurde-geandert" aria-label="Permalink to &quot;Qu&#39;est-ce qui a changé ? {#was-wurde-geandert}&quot;">​</a></h2><p>L&#39;ancien système de thèmes a été entièrement supprimé. HADash utilise désormais les couleurs et les contrôles standard de Windows.</p><p>Par conséquent, l&#39;interface est désormais :</p><ul><li>moins encombrée</li><li>plus facile à lire</li><li>moins sujette aux erreurs</li><li>plus cohérente avec les autres applications Windows</li></ul><h2 id="hadash" tabindex="-1">HADash <a class="header-anchor" href="#hadash" aria-label="Permalink to &quot;HADash {#hadash}&quot;">​</a></h2><p>HADash est une application Windows portable permettant d&#39;importer, de sauvegarder et d&#39;exporter des tableaux de bord Home Assistant.</p><p>Le programme permet, entre autres, de :</p><ul><li>Lire des données JSON à partir de sauvegardes Home Assistant non chiffrées</li><li>Traiter le contenu du dossier <code>.storage</code></li><li>Enregistrer des tableaux de bord complets au format YAML</li><li>Sélectionner et exporter des vues individuelles</li><li>Enregistrer des vues au format TXT, YAML ou sous forme de tableau de bord complet</li></ul><h2 id="download" tabindex="-1">Téléchargement <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Téléchargement {#download}&quot;">​</a></h2><p>La version préliminaire actuelle est disponible via GitHub :</p><p><a href="https://github.com/rockbaer2007/HADash/releases" target="_blank" rel="noreferrer">Accéder aux versions de HADash</a></p><h2 id="dokumentation" tabindex="-1">Documentation <a class="header-anchor" href="#dokumentation" aria-label="Permalink to &quot;Documentation {#dokumentation}&quot;">​</a></h2><p><a href="/fr/projects/hadash/">Consulter la documentation de HADash</a></p>',17)])])}const m=a(i,[["render",o]]);export{c as __pageData,m as default};
